<template><view class="batch-page"><NativeStatusSpacer/><view class="nav"><button class="back" @tap="back">‹</button><text>批量配置班级</text></view><view class="paper"><text v-if="error" class="error">{{error}}</text><text v-if="loading" class="state">正在核对成员</text><template v-if="source"><view class="source"><text>{{source.name}}</text><text>已选 {{members.length}} 名成员</text></view><view class="names"><text v-for="member in members" :key="member.studentId">{{member.studentName}}</text></view><template v-if="!completed"><text class="label">目标班级<text class="required">*</text></text><picker :range="targetLabels" :value="targetIndex" :disabled="busy||uncertain" @change="targetIndex=Number($event.detail.value)"><view class="picker">{{target?.name||'请选择同一学校或机构的班级'}}<text>›</text></view></picker><text class="intent">{{institutionType==='TRAINING_INSTITUTION'?'为所选成员增加目标班级，保留原班级关系。':'将所选成员转入目标班级。'}}</text><text class="label">调整原因<text class="required">*</text></text><textarea v-model="reason" maxlength="200" :disabled="busy||uncertain" placeholder="请填写调整原因"/><button class="primary" :loading="requesting" :disabled="busy||uncertain||!target" @tap="submit">确认配置 {{members.length}} 名成员</button></template><view v-else class="result">已完成 {{completed}} 名成员的班级配置</view></template><button v-if="completed||uncertain" class="secondary" @tap="back">返回班级核对</button></view></view></template>
<script setup lang="ts">
import {ref,computed} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';import {getOrganizationSession} from '@/session/organization-session';import {request} from '@/api/http';import {listManagedClasses,type OrganizationClass} from '@/api/organization-classes';import {listOrganizationStudents,type OrganizationStudentRelationship} from '@/api/organization-students';import {classMemberApi} from '@/api/class-members';import {batchConfigurationDraft,validateBatchSelection} from '@/models/class-batch-draft';import {membersOfClass} from '@/models/class-detail';
const source=ref<OrganizationClass|null>(null),targets=ref<OrganizationClass[]>([]),members=ref<OrganizationStudentRelationship[]>([]),targetIndex=ref(-1),reason=ref(''),loading=ref(false),acting=ref(false),requesting=ref(false),uncertain=ref(false),completed=ref(0),error=ref('');const busy=computed(()=>loading.value||acting.value),target=computed(()=>targets.value[targetIndex.value]),targetLabels=computed(()=>targets.value.map(c=>`${c.gradeName?c.gradeName+' · ':''}${c.name}`));let sourceId='',ids:string[]=[],token='',schoolId='',institutionType='',revision=0,visible=false;
function selected(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function sameScope(){const s=selected();return !!token&&getOrganizationSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===schoolId&&s.typeCode===institutionType;}
function current(n:number){return visible&&n===revision&&sameScope();}
onLoad(q=>{sourceId=typeof q?.classId==='string'?q.classId:'';ids=typeof q?.ids==='string'?q.ids.split(','):[];});onShow(()=>{visible=true;void load();});function hide(){visible=false;if(requesting.value)uncertain.value=true;++revision;loading.value=false;acting.value=false;requesting.value=false;source.value=null;members.value=[];targets.value=[];}onHide(hide);onUnload(hide);
async function load(){const n=++revision,nextToken=getOrganizationSession()?.accessToken||'',s=selected();if(token&&token!==nextToken){reason.value='';uncertain.value=false;completed.value=0;}token=nextToken;schoolId=s?.organizationId||'';institutionType=s?.typeCode||'';source.value=null;targets.value=[];members.value=[];targetIndex.value=-1;loading.value=true;error.value='';let checked=false;try{if(!/^[1-9]\d{0,18}$/.test(sourceId)||!sameScope()||!['SCHOOL','TRAINING_INSTITUTION'].includes(institutionType))throw Error('请从当前组织的班级进入');validateBatchSelection(ids);checked=true;const me=await request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}});if(!current(n))return;if(!me.permissionCodes.includes('CLASS_READ')||!me.permissionCodes.includes('STUDENT_ORGANIZATION_MANAGE'))throw Error('当前账号没有批量配置成员权限');const classes=await listManagedClasses(token);if(!current(n))return;const c=classes.find(c=>c.id===sourceId&&c.schoolOrganizationId===schoolId&&c.status==='ENABLED'&&c.effectiveStatus==='ENABLED');if(!c)throw Error('来源班级已变化或不可管理');const rows=await listOrganizationStudents(token);if(!current(n))return;const actual=membersOfClass(rows,sourceId);if(ids.some(id=>!actual.some(m=>m.studentId===id)))throw Error('所选成员班级关系已变化，请返回重新选择');members.value=actual.filter(m=>ids.includes(m.studentId));targets.value=classes.filter(t=>t.id!==sourceId&&t.schoolOrganizationId===schoolId&&t.status==='ENABLED'&&t.effectiveStatus==='ENABLED');source.value=c;if(uncertain.value)error.value='上次操作结果待确认，请先返回班级核对。';}catch(e){if(current(n)||!checked&&visible&&n===revision)error.value=e instanceof Error?e.message:'加载未完成';}finally{if(n===revision)loading.value=false;}}
async function submit(){if(busy.value||uncertain.value||completed.value||!source.value)return;const n=revision;error.value='';let checked=false;try{if(!current(n)||!target.value)throw Error('组织或目标班级已变化，请重新选择');checked=true;const data=batchConfigurationDraft(ids,target.value.id,reason.value);acting.value=true;const confirmation=await uni.showModal({title:'批量配置班级',content:`确认${institutionType==='TRAINING_INSTITUTION'?'为':'将'} ${ids.length} 名成员${institutionType==='TRAINING_INSTITUTION'?'增加':'转入'} ${target.value.name}？`,confirmText:'确认'});if(!confirmation.confirm||!current(n))return;requesting.value=true;const response=await classMemberApi.configureBatch(token,schoolId,sourceId,data.targetClassId,data.studentIds,data.reason);if(!current(n)){uncertain.value=true;return;}if(response.affectedCount!==ids.length||!Array.isArray(response.studentIds)||response.studentIds.length!==ids.length||new Set(response.studentIds).size!==ids.length||ids.some(id=>!response.studentIds.includes(id))){uncertain.value=true;throw Error('操作结果待核对，请返回班级确认');}completed.value=response.affectedCount;}catch(e){if(current(n)||!checked&&visible&&n===revision)error.value=e instanceof Error?e.message:'操作未完成，请核对结果';}finally{if(n===revision){acting.value=false;requesting.value=false;}}}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/organization-class-detail/organization-class-detail?classId='+encodeURIComponent(sourceId)})});}
</script>
<style scoped>.batch-page{min-height:100vh;background:#f6faf7;color:#193d31}.nav{height:88rpx;position:relative;display:flex;align-items:center;justify-content:center;background:white;font-size:30rpx;font-weight:650}.back{position:absolute;left:16rpx;width:54rpx;padding:0;margin:0;background:transparent;color:#204f3c;font-size:58rpx;font-weight:300}button::after{border:0}.paper{background:white;border-radius:28rpx;padding:30rpx}.source{display:flex;justify-content:space-between;gap:20rpx;align-items:center;font-size:28rpx}.source>text:first-child{font-weight:650;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.source>text:last-child{font-size:24rpx;color:#84958a;flex-shrink:0}.names{display:flex;flex-wrap:wrap;gap:10rpx;margin:20rpx 0 28rpx}.names text{font-size:24rpx;color:#4e7460;background:#eff5f0;border-radius:14rpx;max-width:240rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:7rpx 15rpx}.label{display:block;font-size:28rpx;margin:25rpx 0 14rpx}.required{color:#ce5c50;margin-left:7rpx}.picker{display:flex;justify-content:space-between;gap:20rpx;padding:20rpx;background:#f8fbf8;border:1rpx solid #dfe8e0;border-radius:17rpx;font-size:28rpx}.intent{display:block;font-size:24rpx;line-height:1.6;color:#6f8b78;margin-top:13rpx}textarea{width:100%;height:155rpx;box-sizing:border-box;padding:18rpx;background:#f8fbf8;border:1rpx solid #dfe8e0;border-radius:17rpx;font-size:28rpx}.primary,.secondary{line-height:90rpx;border-radius:22rpx;background:#155e45;color:white;font-size:29rpx;margin-top:30rpx}.primary[disabled]{background:#a7bdb0;color:white}.secondary{color:#205c42;background:#edf4ee}.state,.error{display:block;font-size:26rpx;line-height:1.6;padding:18rpx 0;color:#86978d}.error{color:#b25146}.result{font-size:31rpx;color:#1a6447;padding:45rpx 0;text-align:center}</style>
